    14  void test_gelf_pack()
    15  {
    16      msgpack_sbuffer mp_sbuf;
    17      msgpack_packer mp_pck;
    18      struct flb_time ts;
    19      struct flb_gelf_fields fields = {0};
    20      flb_sds_t out;
    21
    22      /* Pack sample msgpack */
    23      msgpack_sbuffer_init(&mp_sbuf);
    24      msgpack_packer_init(&mp_pck, &mp_sbuf, msgpack_sbuffer_write);
    25
    26      msgpack_pack_array(&mp_pck, 2);
    27
    28      flb_time_from_double(&ts, 337647600.0);
    29      flb_time_append_to_msgpack(&ts, &mp_pck, 0);
    30
    31      msgpack_pack_map(&mp_pck, 2);
    32      msgpack_pack_str(&mp_pck, 2);
    33      msgpack_pack_str_body(&mp_pck, "t1", 2);
    34      msgpack_pack_array(&mp_pck, 3);
    35      msgpack_pack_true(&mp_pck);
    36      msgpack_pack_uint64(&mp_pck, 2019);
    37      msgpack_pack_str(&mp_pck, 3);
    38      msgpack_pack_str_body(&mp_pck, "str", 3);
    39      msgpack_pack_str(&mp_pck, 2);
    40      msgpack_pack_str_body(&mp_pck, "t2", 2);
    41      msgpack_pack_false(&mp_pck);
    42
    43      fields.short_message_key = flb_sds_create("t1");
    44      out = flb_msgpack_raw_to_gelf(mp_sbuf.data, mp_sbuf.size, &ts, &fields);
    45      TEST_CHECK(out != NULL);
    46
    47      TEST_CHECK(strcmp(out, EXPECTED_OUT) == 0);
    48      printf("%s", out);
    49      flb_sds_destroy(out);
    50      flb_sds_destroy(fields.short_message_key);
    51      msgpack_sbuffer_destroy(&mp_sbuf);
    52  }
